import * as THREE from 'three';
import type { Wall, Point } from './types';
// ============================================================
// ✅ استخراج Footprint المبنى من الجدران الخارجية
// ============================================================
const EPS = 0.10;
/**
 * ✅ خط المنتصف لكل جدار
  */
  function getWallCenterline(w: Wall): { a: Point; b: Point } {
    return { a: { ...w.start }, b: { ...w.end } };
    }
    /**
     * ✅ ترتيب القطاعات في حلقات
      */
      function orderSegmentsIntoLoops(
        segments: { a: Point; b: Point }[],
        ): Point[][] {
          const loops: Point[][] = [];
            const used = new Set<number>();
              while (used.size < segments.length) {
                  let startIdx = -1;
                      for (let i = 0; i < segments.length; i++) {
                            if (!used.has(i)) { startIdx = i; break; }
                                }
                                    if (startIdx < 0) break;
                                        const loop: Point[] = [];
                                            let currentIdx = startIdx;
                                                let currentPoint = segments[startIdx].a;
                                                    loop.push({ ...currentPoint });
                                                        let safety = 0;
                                                            while (safety++ < segments.length + 2) {
                                                                  used.add(currentIdx);
                                                                        const seg = segments[currentIdx];
                                                                              const isBEnd = Math.hypot(seg.b.x - currentPoint.x, seg.b.y - currentPoint.y) < EPS;
                                                                                    const nextPoint = isBEnd ? seg.a : seg.b;
                                                                                          if (loop.length > 1 && Math.hypot(nextPoint.x - loop[0].x, nextPoint.y - loop[0].y) < EPS) {
                                                                                                  break;
                                                                                                        }
                                                                                                              loop.push({ ...nextPoint });
                                                                                                                    currentPoint = nextPoint;
                                                                                                                          let found = -1;
                                                                                                                                for (let i = 0; i < segments.length; i++) {
                                                                                                                                        if (used.has(i)) continue;
                                                                                                                                                const s = segments[i];
                                                                                                                                                        if (
                                                                                                                                                                  Math.hypot(s.a.x - currentPoint.x, s.a.y - currentPoint.y) < EPS ||
                                                                                                                                                                            Math.hypot(s.b.x - currentPoint.x, s.b.y - currentPoint.y) < EPS
                                                                                                                                                                                    ) {
                                                                                                                                                                                              found = i;
                                                                                                                                                                                                        break;
                                                                                                                                                                                                                }
                                                                                                                                                                                                                      }
                                                                                                                                                                                                                            if (found < 0) break;
                                                                                                                                                                                                                                  currentIdx = found;
                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                          if (loop.length >= 3) {
                                                                                                                                                                                                                                                loops.push(loop);
                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                        return loops;
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                        function signedArea(polygon: Point[]): number {
                                                                                                                                                                                                                                                          let area = 0;
                                                                                                                                                                                                                                                            for (let i = 0; i < polygon.length; i++) {
                                                                                                                                                                                                                                                                const j = (i + 1) % polygon.length;
                                                                                                                                                                                                                                                                    area += polygon[i].x * polygon[j].y - polygon[j].x * polygon[i].y;
                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                        return area / 2;
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                        function ensureCCW(polygon: Point[]): Point[] {
                                                                                                                                                                                                                                                                          return signedArea(polygon) < 0 ? [...polygon].reverse() : polygon;
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                          /**
                                                                                                                                                                                                                                                                           * ✅ مركز المضلّع
                                                                                                                                                                                                                                                                            */
                                                                                                                                                                                                                                                                            export function polygonCentroid(polygon: Point[]): Point {
                                                                                                                                                                                                                                                                              if (polygon.length === 0) return { x: 0, y: 0 };
                                                                                                                                                                                                                                                                                let sx = 0, sy = 0;
                                                                                                                                                                                                                                                                                  polygon.forEach(p => { sx += p.x; sy += p.y; });
                                                                                                                                                                                                                                                                                    return { x: sx / polygon.length, y: sy / polygon.length };
                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                    /**
                                                                                                                                                                                                                                                                                     * ✅ توسيع المضلّع للخارج (تقديري — من المركز)
                                                                                                                                                                                                                                                                                      */
                                                                                                                                                                                                                                                                                      function offsetPolygonOutward(polygon: Point[], distance: number): Point[] {
                                                                                                                                                                                                                                                                                        if (polygon.length < 3) return polygon;
                                                                                                                                                                                                                                                                                          const c = polygonCentroid(polygon);
                                                                                                                                                                                                                                                                                            return polygon.map(p => {
                                                                                                                                                                                                                                                                                                const dx = p.x - c.x;
                                                                                                                                                                                                                                                                                                    const dy = p.y - c.y;
                                                                                                                                                                                                                                                                                                        const len = Math.hypot(dx, dy) || 1;
                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                  x: p.x + (dx / len) * distance,
                                                                                                                                                                                                                                                                                                                        y: p.y + (dy / len) * distance,
                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                              export interface FootprintResult {
                                                                                                                                                                                                                                                                                                                                polygon: Point[];
                                                                                                                                                                                                                                                                                                                                  loops: Point[][];
                                                                                                                                                                                                                                                                                                                                    valid: boolean;
                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                    /**
                                                                                                                                                                                                                                                                                                                                     * ✅ الدالة الرئيسية
                                                                                                                                                                                                                                                                                                                                      */
                                                                                                                                                                                                                                                                                                                                      export function extractBuildingFootprint(walls: Wall[]): FootprintResult {
                                                                                                                                                                                                                                                                                                                                        // 1. الجدران الخارجية فقط
                                                                                                                                                                                                                                                                                                                                          const exteriorWalls = walls.filter(
                                                                                                                                                                                                                                                                                                                                              w => w.type === 'exterior' && (w.kind === undefined || w.kind === 'wall'),
                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                  if (exteriorWalls.length < 3) {
                                                                                                                                                                                                                                                                                                                                                      return { polygon: [], loops: [], valid: false };
                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                          // 2. استخدام خط المنتصف (يضمن الاتصال عند الزوايا)
                                                                                                                                                                                                                                                                                                                                                            const segments = exteriorWalls.map(getWallCenterline);
                                                                                                                                                                                                                                                                                                                                                              // 3. ترتيب في حلقات
                                                                                                                                                                                                                                                                                                                                                                const loops = orderSegmentsIntoLoops(segments);
                                                                                                                                                                                                                                                                                                                                                                  if (loops.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                      return { polygon: [], loops: [], valid: false };
                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                          // 4. أكبر حلقة
                                                                                                                                                                                                                                                                                                                                                                            let largest = loops[0];
                                                                                                                                                                                                                                                                                                                                                                              let largestArea = Math.abs(signedArea(largest));
                                                                                                                                                                                                                                                                                                                                                                                for (let i = 1; i < loops.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                    const area = Math.abs(signedArea(loops[i]));
                                                                                                                                                                                                                                                                                                                                                                                        if (area > largestArea) {
                                                                                                                                                                                                                                                                                                                                                                                              largestArea = area;
                                                                                                                                                                                                                                                                                                                                                                                                    largest = loops[i];
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                            if (largest.length < 3) {
                                                                                                                                                                                                                                                                                                                                                                                                                return { polygon: [], loops, valid: false };
                                                                                                                                                                                                                                                                                                                                                                                                                  }
// 5. ✅ السقف يتبع حافة الجدار بالضبط (بدون إزاحة)
return {
  polygon: ensureCCW(largest),
    loops,
      valid: true,
      };                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                            /**
                                                                                                                                                                                                                                                                                                                                                                                                                                             * ✅ تحويل المضلّع إلى THREE.Shape
                                                                                                                                                                                                                                                                                                                                                                                                                                              */
                                                                                                                                                                                                                                                                                                                                                                                                                                              export function polygonToShape(polygon: Point[]): THREE.Shape | null {
                                                                                                                                                                                                                                                                                                                                                                                                                                                if (polygon.length < 3) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                  const shape = new THREE.Shape();
                                                                                                                                                                                                                                                                                                                                                                                                                                                    shape.moveTo(polygon[0].x, polygon[0].y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                      for (let i = 1; i < polygon.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                          shape.lineTo(polygon[i].x, polygon[i].y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                              shape.closePath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                return shape;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * ✅ معلومات كل حافة
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  export interface EdgeInfo {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    midX: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      midZ: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        angle: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          len: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            outX: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              outZ: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              export function getEdgeInfos(polygon: Point[]): EdgeInfo[] {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (polygon.length < 3) return [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const centroid = polygonCentroid(polygon);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const edges: EdgeInfo[] = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      for (let i = 0; i < polygon.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const p1 = polygon[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const p2 = polygon[(i + 1) % polygon.length];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const dx = p2.x - p1.x;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const dz = p2.y - p1.y;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const len = Math.hypot(dx, dz);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (len < 0.01) continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const midX = (p1.x + p2.x) / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const midZ = (p1.y + p2.y) / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const angle = Math.atan2(-dz, dx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const n1 = { x: dz / len, y: -dx / len };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const n2 = { x: -dz / len, y: dx / len };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const test1X = midX + n1.x * 0.1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const test1Z = midZ + n1.y * 0.1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const test2X = midX + n2.x * 0.1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const test2Z = midZ + n2.y * 0.1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const d1 = Math.hypot(test1X - centroid.x, test1Z - centroid.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const d2 = Math.hypot(test2X - centroid.x, test2Z - centroid.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const outward = d1 > d2 ? n1 : n2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  edges.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        midX,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              midZ,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    angle,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          len,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                outX: outward.x,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      outZ: outward.y,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return edges;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }